/**
 * @file    CanTp_Cfg.h
 * @brief   Pre-compile configuration of the example CanTp.
 *
 * In a real project this file is GENERATED by the configuration tool from the
 * ECUC values (ARXML). Each macro names the ECUC parameter it represents
 * (AUTOSAR CP R25-11 SWS_CANTransportLayer, chapter 10).
 * Numeric values are EXAMPLE values chosen for this exercise.
 *
 * Example network (CAN IDs are known by CanIf/LSduR, not by CanTp):
 *   0x7E0  tester -> ECU, physical : request SF/FF/CF + FC for ECU responses
 *   0x7DF  tester -> ECU, functional: request SF only
 *   0x7E8  ECU -> tester            : response SF/FF/CF + FC for requests
 */
#ifndef CANTP_CFG_H
#define CANTP_CFG_H

#include "ComStack_Types.h"

/* ---- CanTpGeneral -------------------------------------------------------- */
#define CANTP_DEV_ERROR_DETECT           STD_ON           /* CanTpDevErrorDetect      */
#define CANTP_CHANGE_PARAMETER_API       STD_ON           /* CanTpChangeParameterApi  */
#define CANTP_READ_PARAMETER_API         STD_ON           /* CanTpReadParameterApi    */
#define CANTP_FLEXIBLE_DATA_RATE_SUPPORT STD_OFF          /* CanTpFlexibleDataRateSupport */

/* CanTpPaddingByte. The macro name CANTP_PADDING_BYTE is used by
 * [SWS_CanTp_00059]. 0xCC is an example value [Practice]. */
#define CANTP_PADDING_BYTE               ((uint8)0xCCu)

/* ---- CanTpConfig/CanTpMainFunctionPeriod = 0.001 s ----------------------- */
#define CANTP_MAIN_FUNCTION_PERIOD_MS    1u

/* Converts a time in ms (ECUC float in seconds * 1000) into main function
 * ticks, rounded up. The generator would do this conversion [Inference]. */
#define CANTP_MS_TO_TICKS(ms)  ((uint16)(((ms) + CANTP_MAIN_FUNCTION_PERIOD_MS - 1u) / CANTP_MAIN_FUNCTION_PERIOD_MS))

/* ---- Symbolic handle IDs -------------------------------------------------
 * Pattern CanTpConf_<Container>_<ShortName> [Practice].                     */

/* CanTpRxNSduId: used in CanTp_CancelReceive / ChangeParameter / ReadParameter */
#define CanTpConf_CanTpRxNSdu_DiagPhysRx          ((PduIdType)0u)
#define CanTpConf_CanTpRxNSdu_DiagFuncRx          ((PduIdType)1u)
#define CANTP_CFG_NUM_RX_NSDU                     2u

/* CanTpTxNSduId: used in CanTp_Transmit / CanTp_CancelTransmit */
#define CanTpConf_CanTpTxNSdu_DiagTx              ((PduIdType)0u)
#define CANTP_CFG_NUM_TX_NSDU                     1u

/* RxPduId of CanTp_RxIndication. CanTpRxNPdu and CanTpRxFcNPdu that refer to
 * the same L-PDU (0x7E0) share one handle [Inference]. */
#define CanTpConf_CanTpRxNPdu_Req7E0              ((PduIdType)0u)
#define CanTpConf_CanTpRxNPdu_FuncReq7DF          ((PduIdType)1u)
#define CanTpConf_CanTpRxFcNPdu_Req7E0            ((PduIdType)0u)

/* TxPduId of CanTp_TxConfirmation: CanTpTxNPduConfirmationPduId and
 * CanTpTxFcNPduConfirmationPduId. Both refer to the L-PDU 0x7E8. */
#define CanTpConf_CanTpTxNPdu_Resp7E8             ((PduIdType)0u)
#define CanTpConf_CanTpTxFcNPdu_Resp7E8           ((PduIdType)0u)

/* TxPduId passed to LSduR_CanTpTransmit. The value belongs to the LSduR
 * configuration (resolved from CanTpTxNPduRef / CanTpTxFcNPduRef). */
#define CANTP_CFG_LSDUR_TX_RESP7E8                ((PduIdType)0u)

/* id passed to PduR_CanTp<...>. The value belongs to the PduR configuration
 * (resolved from CanTpRxNSduRef / CanTpTxNSduRef). */
#define CANTP_CFG_PDUR_DIAG_PHYS_RX               ((PduIdType)0u)
#define CANTP_CFG_PDUR_DIAG_FUNC_RX               ((PduIdType)1u)
#define CANTP_CFG_PDUR_DIAG_TX                    ((PduIdType)0u)

#endif /* CANTP_CFG_H */
